  async setCount(name, subject, data) {

    let findcount = await data.find(n => {

      if (n == undefined) {
        return { count: 0 }
      } else if (n.class == name && n.subject == subject) {
        return n
      }
    });

    if (findcount != undefined) {
      return findcount.count
    } else {
      return 0
    }
  }


